    public static long newMovementCommand(int mode) {
        if (mode == MOVE_NORMAL && isExternalMovementControlActive()) {
            return movementCommandId.get();
        }
        movementMode = mode;
        return movementCommandId.incrementAndGet();
    }

    public static boolean isMovementCommandValid(long commandId, int mode) {
        return movementCommandId.get() == commandId && movementMode == mode;
    }

    public static boolean isExternalMovementControlActive() {
        int mode = movementMode;
        return mode == MOVE_JUMP || mode == MOVE_PHASE_STEP;
    }

