    public static String normalize(String string) {
        if (string == null) {
            return "";
        }
        String string2 = Normalizer.normalize(string, Normalizer.Form.NFD);
        string2 = string2.replaceAll("\\p{InCombiningDiacriticalMarks}+", "");
        string2 = string2.replace('\u0111', 'd').replace('\u0110', 'd');
        string2 = string2.replace('?', ' ');
        string2 = string2.replaceAll("[^a-zA-Z0-9 ]", " ");
        string2 = string2.replaceAll("\\s+", " ").trim();
        return string2.toLowerCase();
    }

